    loftee_variants = dataproc_result.select()
    hail_vep_result = hl.vep(loftee_variants, self.vep_config_grch38_95)
    hail_vep_result = hail_vep_result.annotate(vep=hail_vep_result.vep.annotate(input=hl.str('\t').join([hail_vep_result.locus.contig, hl.str(hail_vep_result.locus.position), '.', hail_vep_result.alleles[0], hail_vep_result.alleles[1], '.', '.', 'GT'])))
    hail_vep_result = hail_vep_result.select('vep')

    def parse_lof_info_into_dict(ht):

        def tuple2(arr):
            return hl.tuple([arr[0], arr[1]])
        return ht.annotate(vep=ht.vep.annotate(transcript_consequences=ht.vep.transcript_consequences.map(lambda csq: csq.annotate(lof_info=hl.or_missing(csq.lof_info != 'null', hl.dict(csq.lof_info.split(',').map(lambda kv: tuple2(kv.split(':')))))))))
